import {dayWorkout,plans,muscles,levels} from './data.js';
import {currentLocale} from './i18n.js';

const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=(d,options={day:'numeric',month:'long'})=>d.toLocaleDateString(currentLocale(),options);
export function planSummary(state){
 const scheduled=Array.from({length:28},(_,i)=>i).filter(i=>!dayWorkout(state,state.plan,i).rest);
 const completed=new Set((state.history||[]).filter(h=>h.start===state.start&&scheduled.includes(h.day)).map(h=>h.day));
 return {scheduled,completed,total:scheduled.length,done:completed.size,percent:Math.round(completed.size/scheduled.length*100)};
}
const weeks=[['Tekniğini bul','Hareketleri tanı. Kontrollü ve rahat bir yükle başla.'],['Ritmini koru','Planına yer aç. Setlerini ve tekrarlarını kaydet.'],['Kendini gözlemle','Önceki seanslarınla karşılaştır. İyi formu öncelikli tut.'],['Geriye bak, ileriye hazırlan','Dört haftanın kayıtlarını değerlendir. İhtiyacına göre dinlen.']];
function levelMarkup(state){
 const p=plans.find(p=>p.id===state.plan)||plans[1];
 return `<section class="level-studio" aria-label="Program seviyesi"><div class="level-heading"><div><span class="eyebrow">KENDİ TEMPOUNDA</span><h2>Seviyeni seç.</h2></div><span class="level-note">Hazır plan · Seans başına hareket</span></div><div class="level-options">${levels.map((l,i)=>{const counts=p.pattern.map(day=>dayWorkout({...state,level:l.id,planEdits:{}},p.id,day).exercises.length),min=Math.min(...counts),max=Math.max(...counts);return `<button data-action="level-change" data-value="${l.id}" class="level-card" aria-pressed="${(state.level||'beginner')===l.id}" ${state.activeSession?'disabled':''}><span class="level-bars" aria-hidden="true">${[0,1,2].map(n=>`<i class="${n<=i?'lit':''}"></i>`).join('')}</span><strong>${l.name}</strong><span>${min===max?min:min+'–'+max} hareket</span><small>${l.description}</small><span class="level-check" aria-hidden="true">✓</span></button>`}).join('')}</div><p>${state.activeSession?'Önce kayıtlı seansını tamamla.':'Seviyeyi hazır hissettiğinde artır. Formun bozulursa veya toparlanman uzarsa azalt.'}</p><small>Özelleştirdiğin günler her seviye için ayrı saklanır.</small></section>`;
}

export function planStudio(state,{selectedDay,today,next,dayDate,profileBar,routinePanel,detail}){
 const p=plans.find(p=>p.id===state.plan)||plans[1],s=planSummary(state),week=Math.floor(selectedDay/7),w=dayWorkout(state,state.plan,selectedDay);
 const nextPlan=next>=0?dayWorkout(state,state.plan,next):null;
 const current=dayWorkout(state,state.plan,today),todayDate=date(dayDate(today)),isToday=date(dayDate(today),{year:'numeric',month:'numeric',day:'numeric'})===date(new Date(),{year:'numeric',month:'numeric',day:'numeric'});
 const status=state.activeSession?'SEANSIN SENİ BEKLİYOR':s.done===s.total?'DÖRT HAFTALIK EMEĞİN':!isToday?'YENİ BİR RİTME HAZIR MISIN?':current.rest?'BUGÜN · AKTİF DİNLENME':s.completed.has(today)?'BUGÜN · TAMAMLANDI':'BUGÜN · SENİN ZAMANIN';
 const heroTitle=state.activeSession?'Kaldığın yerden.':s.done===s.total?'Her seans bir adım.':!isToday?'Yeni bir sayfa.':current.rest?'Dinlenmek de planın parçası.':s.completed.has(today)?'Bugün kendine zaman ayırdın.':current.title;
 const heroCopy=state.activeSession?'Kaydettiğin setler yerinde. Hazır olduğunda devam et.':s.done===s.total?'Planındaki tüm seanslar kaydedildi. Gelişimini incele ve sonraki ritmini seç.':!isToday?'Bu planın takvimi sona erdi. Kayıtlarını inceleyebilir veya yeni bir plan başlatabilirsin.':current.rest?'Rahat hareket et, toparlanmaya zaman bırak. Sıradaki seansın burada.':s.completed.has(today)?'Kaydın günlüğüne işlendi. Sıradaki antrenmanına kadar toparlanmaya alan aç.':`${todayDate} · Yaklaşık ${current.minutes} dakika · ${current.exercises.length} hareket`;
 const heroAction=state.activeSession?'<button class="primary" data-action="resume">Seansıma devam et <span>↗</span></button>':isToday&&!current.rest&&!s.completed.has(today)?`<button class="primary" data-action="start" data-day="${today}">Antrenmana başla <span>↗</span></button>`:nextPlan?`<button class="secondary" data-action="plan-jump" data-day="${next}">Sıradaki seansı incele <span>↗</span></button>`:'<a class="secondary" href="#progress">Gelişimimi incele ↗</a>';
 const strengthSets=w.exercises.reduce((n,e)=>n+(e.category==='strength'?(e.sets||w.sets):0),0);
 const targets=[...new Set(w.exercises.map(e=>e.muscle))];
 return `<div class="plan-workspace">
 <div class="plan-page-heading"><div><span class="eyebrow">ANTRENMAN TAKVİMİN</span><h1>Bir plan. Senin ritmin.</h1><p>${escape(p.name)} · ${date(dayDate(0))} – ${date(dayDate(27))}</p></div><div class="plan-heading-actions"><button class="primary" data-feature="routine-new">Sıfırdan program oluştur</button><button class="ghost" data-action="plan-options">Planı değiştir <span>⇄</span></button></div></div>
 ${levelMarkup(state)}
 <section class="plan-focus"><div class="plan-focus-copy"><span class="eyebrow">${status}</span><h2>${heroTitle}</h2><p>${heroCopy}</p><div class="plan-focus-action">${heroAction}${nextPlan&&(current.rest||s.completed.has(today))?`<small>${date(dayDate(next),{weekday:'long',day:'numeric',month:'long'})} · ≈${nextPlan.minutes} dk</small>`:''}</div></div><div class="plan-completion"><div class="plan-orbit" role="img" aria-label="Plan ilerlemesi: ${s.total} seansın ${s.done} tanesi tamamlandı" style="--complete:${s.percent}%"><div><strong>${s.done}<span> / ${s.total}</span></strong><small>seans tamamlandı</small></div></div><div class="plan-completion-caption"><span>%${s.percent}</span> Kendi hızında, düzenli adımlarla.</div></div></section>
 ${profileBar(state)}
 <section class="plan-agenda" aria-label="Dört haftalık antrenman takvimi"><div class="agenda-heading"><div><span class="eyebrow">4 HAFTA · KÜÇÜK ADIMLAR</span><h2>Haftanı gör. Gününü seç.</h2></div><button class="text-button" data-action="plan-today">Bugüne dön ↙</button></div>
 <div class="plan-weeks" role="tablist" aria-label="Antrenman haftaları">${weeks.map((info,i)=>{const days=s.scheduled.filter(d=>Math.floor(d/7)===i),count=days.filter(d=>s.completed.has(d)).length;return `<button role="tab" id="plan-week-${i}" aria-controls="week-panel" aria-selected="${i===week}" tabindex="${i===week?0:-1}" data-action="plan-week" data-week="${i}"><span>0${i+1}<b>${i+1}. hafta</b></span><small>${count} / ${days.length} seans</small><i aria-hidden="true" style="--week-done:${count/days.length*100}%"></i></button>`}).join('')}</div>
 <div role="tabpanel" id="week-panel" aria-labelledby="plan-week-${week}"><div class="plan-week-days">${Array.from({length:7},(_,j)=>{const i=week*7+j,d=dayWorkout(state,state.plan,i),complete=s.completed.has(i),active=i===selectedDay;return `<button class="plan-date ${active?'is-selected':''} ${d.rest?'is-rest':'is-training'} ${complete?'is-done':''}" data-action="day" data-day="${i}" aria-pressed="${active}" ${isToday&&i===today?'aria-current="date"':''} aria-label="${date(dayDate(i),{weekday:'long',day:'numeric',month:'long'})} · ${d.rest?'Dinlenme':d.title}${complete?' · Tamamlandı':''}"><span>${date(dayDate(i),{weekday:'short'})}</span><strong>${dayDate(i).getDate()}</strong><small>${complete?'✓ Bitti':d.rest?'Dinlenme':'Antrenman'}</small></button>`}).join('')}</div>
 <div class="week-focus-note"><span aria-hidden="true">✦</span><p><strong>${weeks[week][0]}</strong>${weeks[week][1]}</p></div>
 <div class="plan-day-layout"><div class="plan-day-content" id="plan-detail">${detail()}${!w.rest?`<div class="plan-edit-actions"><button class="secondary" data-feature="plan-edit" data-day="${selectedDay}" ${state.activeSession?'disabled':''}>Egzersiz ekle / çıkar</button>${w.customized?`<span class="customized-tag">Kişiselleştirildi</span><button class="text-button" data-feature="plan-reset" data-day="${selectedDay}" ${state.activeSession?'disabled':''}>Hazır listeye dön</button>`:''}</div>${w.missingEquipment?.length?'<p class="tip">Bazı hareketlerin ekipmanı seçili değil. Programı düzenle veya antrenman alanını değiştir.</p>':''}`:''}</div><aside class="plan-session-brief"><span class="eyebrow">SEANSIN ÖZETİ</span><h3>${w.rest?'Toparlanma alanın':w.title}</h3>${w.rest?'<p>Bugün zorunlu bir antrenman yok. Kendini iyi hissediyorsan rahat bir yürüyüş yapabilirsin.</p><a class="text-button" href="#progress">Bu haftaki çalışmam ↗</a>':`<div class="session-brief-metrics"><div><strong>${w.exercises.length}</strong><span>hareket</span></div><div><strong>${strengthSets}</strong><span>kuvvet seti</span></div><div><strong>≈${w.minutes}</strong><span>dakika</span></div></div><p>Çalışacağın ana kas grupları</p><div class="plan-targets">${targets.map(k=>`<button data-action="plan-muscle" data-value="${k}">${muscles[k].name}<span>↗</span></button>`).join('')}</div><small>Hareketleri tek tek açarak video ve teknik rehberini inceleyebilirsin.</small>`}</aside></div></div></section>
 <details class="plan-options" id="plan-options"><summary><div><span class="eyebrow">HEDEFİNE ALAN AÇ</span><h2>Ritmini değiştirmek istersen.</h2></div><span class="disclosure-icon" aria-hidden="true">＋</span></summary><p>Bir plan seçip ayrıntılarını incele. Onayladığında yeni dört haftalık takvimin başlar; geçmiş seansların saklanır.</p><div class="plan-grid">${plans.map((x,i)=>`<button class="plan-card ${x.id===state.plan?'selected':''}" data-action="plan-preview" data-value="${x.id}" aria-pressed="${x.id===state.plan}"><span class="plan-num">0${i+1} / 04</span><h3>${x.name}</h3><p>${x.desc}</p><div class="plan-days">${x.days} gün <span>/ hafta · ≈${x.minutes} dk</span></div><span class="plan-select">${x.id===state.plan?'✓ Aktif planın':'Planı incele ↗'}</span></button>`).join('')}</div><button class="text-button" data-action="setup">Hedefimi ve seviyemi düzenle ↗</button></details>
 ${routinePanel(state)}
 ${state.activeSession?'<div class="plan-mobile-dock"><div><small>KAYITLI SEANS</small><strong>Kaldığın yerden devam et</strong></div><button class="primary" data-action="resume">Devam et ↗</button></div>':!w.rest&&!s.completed.has(selectedDay)?`<div class="plan-mobile-dock"><div><small>${date(dayDate(selectedDay))} · ≈${w.minutes} DK</small><strong>${w.title}</strong></div><button class="primary" data-action="start" data-day="${selectedDay}" ${w.missingEquipment?.length?'disabled':''}>Başla ↗</button></div>`:''}
 </div>`;
}
